export default async function install(app) {
  const palette = { bakerloo:'#B36305',central:'#E32017',circle:'#FFD300',district:'#00782A','hammersmith-city':'#F3A9BB',jubilee:'#A0A5A9',metropolitan:'#9B0056',northern:'#000000',piccadilly:'#003688',victoria:'#0098D4','waterloo-city':'#95CDBA' };
  const trainFields = [{name:'vehicle_id',type:'string'},{name:'line_id',type:'string'},{name:'line_name',type:'string'},{name:'station',type:'string'},{name:'platform',type:'string'},{name:'destination',type:'string'},{name:'seconds_to_station',type:'double'},{name:'status',type:'string'},{name:'observed_at',type:'string'}];
  const trainSymbols = Object.entries(palette).map(([value,color])=>({value,symbol:{type:'simple-marker',style:'circle',color,size:8,outline:{color:'#fff',width:1}}}));
  const roundel = `<div style="font-family:Arial,sans-serif;color:#1d1d1b;margin:-8px -10px -10px;background:#fff"><div style="height:60px;background:#0019a8;display:flex;align-items:center;justify-content:center;position:relative"><div style="width:43px;height:43px;border-radius:50%;background:#e32017;border:6px solid #fff;box-sizing:border-box;position:absolute;left:20px"></div><span style="background:#0019a8;color:#fff;font-size:11px;font-weight:800;letter-spacing:.7px;padding:4px 7px;z-index:1">UNDERGROUND</span></div>`;
  const trainPopup = roundel+`<div style="padding:15px 16px 16px;border-top:5px solid #e32017"><div style="color:#0019a8;font-size:20px;font-weight:800">{line_name} line</div><div style="color:#4b4b4b;font-size:13px;margin:4px 0 13px">Train <b>{vehicle_id}</b> · {status}</div><div style="border-top:1px solid #ddd;padding:9px 0"><b>Next stop</b><br>{station}</div><div style="border-top:1px solid #ddd;padding:9px 0"><b>Towards</b><br>{destination}</div><div style="display:flex;justify-content:space-between;background:#f4f4f4;border-left:4px solid #0019a8;padding:10px 12px"><b>Due in</b><b style="color:#0019a8">{seconds_to_station} sec</b></div></div></div>`;
  const trains = await app.createResultLayer({id:'tfl-live-trains',title:'TfL live trains — refreshed every 5 seconds',geometryType:'point',fields:trainFields,renderer:{type:'unique-value',field:'line_id',uniqueValueInfos:trainSymbols,defaultSymbol:{type:'simple-marker',color:'#777',size:8,outline:{color:'#fff',width:1}}},popupTemplate:{title:'TfL Underground live train',content:[{type:'text',text:trainPopup}]}});
  trains.layer.effect='drop-shadow(2px, 2px, 3px)';
  const response=await fetch(app.config.stationsUrl); app.assert(response.ok,`TfL station directory request failed (${response.status}).`); const directory=await response.json();
  const stationRows=[]; const stations=new Map();
  for(const stop of directory.stopPoints??[]) if(stop.stopType==='NaptanMetroStation'&&Number.isFinite(stop.lat)&&Number.isFinite(stop.lon)){ const lineNames=(stop.lines??[]).map(x=>x.name).join(', '); stations.set(stop.id,[stop.lon,stop.lat]); stationRows.push({geometry:{type:'point',longitude:stop.lon,latitude:stop.lat},attributes:{station_id:String(stop.id),name:String(stop.commonName??''),lines:lineNames,zone:String(stop.additionalProperties?.find(x=>x.category==='Geo'&&x.key==='Zone')?.value??'')}}); }
  const stationsLayer=await app.createResultLayer({id:'tfl-underground-stations',title:'TfL Underground stations',geometryType:'point',fields:[{name:'station_id',type:'string'},{name:'name',type:'string'},{name:'lines',type:'string'},{name:'zone',type:'string'}],renderer:{type:'simple',symbol:{type:'simple-marker',style:'circle',color:'#ffffff',size:7,outline:{color:'#0019a8',width:2}}},popupTemplate:{title:'{name}',content:[{type:'text',text:roundel+`<div style="padding:15px 16px 16px;border-top:5px solid #e32017"><div style="color:#0019a8;font-size:20px;font-weight:800;margin-bottom:12px">{name}</div><div style="border-top:1px solid #ddd;padding:9px 0"><b>Underground lines</b><br>{lines}</div><div style="border-top:1px solid #ddd;padding:9px 0"><b>Fare zone</b><br>{zone}</div></div></div>`}]}});
  stationsLayer.layer.effect='drop-shadow(2px, 2px, 3px)'; await stationsLayer.replaceFeatures(stationRows);
  let busy=false,latest=0; const refresh=async()=>{if(busy)return;busy=true;try{const request=++latest;const r=await fetch(app.config.arrivalsUrl);if(!r.ok)throw new Error(`TfL arrivals request failed (${r.status}).`);const arrivals=await r.json(),byVehicle=new Map();for(const p of arrivals){const prior=byVehicle.get(p.vehicleId);if(!prior||Number(p.timeToStation)<Number(prior.timeToStation))byVehicle.set(p.vehicleId,p);}const features=[];for(const p of byVehicle.values()){const c=stations.get(p.naptanId);if(!c)continue;features.push({geometry:{type:'point',longitude:c[0],latitude:c[1]},attributes:{vehicle_id:String(p.vehicleId??''),line_id:String(p.lineId??''),line_name:String(p.lineName??''),station:String(p.stationName??''),platform:String(p.platformName??''),destination:String(p.destinationName??''),seconds_to_station:Number(p.timeToStation??0),status:String(p.currentLocation??''),observed_at:String(p.timestamp??'')}});}if(request===latest){await trains.replaceFeatures(features);app.setStatus(`TfL stations: ${stationRows.length}; live trains: ${features.length}; updated ${new Date().toLocaleTimeString()}.`);}}catch(error){app.setStatus(`TfL update delayed: ${error.message}`);}finally{busy=false;}};
  await refresh();const timer=setInterval(()=>void refresh(),app.config.refreshMs);app.onCleanup(()=>clearInterval(timer));
}